-- ===== 步骤5: 4批次采购(申请2/1→审批2/5→验收入库2/6) =====
SET @po_id=LAST_INSERT_ID();
UPDATE purchase_order SET total_quantity=(SELECT SUM(quantity) FROM purchase_order_detail WHERE order_id=@po_id), total_amount=(SELECT SUM(amount) FROM purchase_order_detail WHERE order_id=@po_id), received_quantity=(SELECT SUM(quantity) FROM purchase_order_detail WHERE order_id=@po_id), received_amount=(SELECT SUM(amount) FROM purchase_order_detail WHERE order_id=@po_id) WHERE order_id=@po_id;
SET @rc_id=LAST_INSERT_ID();
UPDATE purchase_receipt SET total_quantity=(SELECT SUM(actual_quantity) FROM purchase_receipt_detail WHERE receipt_id=@rc_id), total_amount=(SELECT SUM(amount) FROM purchase_receipt_detail WHERE receipt_id=@rc_id) WHERE receipt_id=@rc_id;
-- 入库→原料档案(关联supplier_id, 全精度unit_price)
-- 成本换算(net_price=采购价÷换算率÷出成率%, Excel全精度单价)

SET @po_id=LAST_INSERT_ID();
UPDATE purchase_order SET total_quantity=(SELECT SUM(quantity) FROM purchase_order_detail WHERE order_id=@po_id), total_amount=(SELECT SUM(amount) FROM purchase_order_detail WHERE order_id=@po_id), received_quantity=(SELECT SUM(quantity) FROM purchase_order_detail WHERE order_id=@po_id), received_amount=(SELECT SUM(amount) FROM purchase_order_detail WHERE order_id=@po_id) WHERE order_id=@po_id;
SET @rc_id=LAST_INSERT_ID();
UPDATE purchase_receipt SET total_quantity=(SELECT SUM(actual_quantity) FROM purchase_receipt_detail WHERE receipt_id=@rc_id), total_amount=(SELECT SUM(amount) FROM purchase_receipt_detail WHERE receipt_id=@rc_id) WHERE receipt_id=@rc_id;
-- 入库→原料档案(关联supplier_id, 全精度unit_price)
-- 成本换算(net_price=采购价÷换算率÷出成率%, Excel全精度单价)

SET @po_id=LAST_INSERT_ID();
UPDATE purchase_order SET total_quantity=(SELECT SUM(quantity) FROM purchase_order_detail WHERE order_id=@po_id), total_amount=(SELECT SUM(amount) FROM purchase_order_detail WHERE order_id=@po_id), received_quantity=(SELECT SUM(quantity) FROM purchase_order_detail WHERE order_id=@po_id), received_amount=(SELECT SUM(amount) FROM purchase_order_detail WHERE order_id=@po_id) WHERE order_id=@po_id;
SET @rc_id=LAST_INSERT_ID();
UPDATE purchase_receipt SET total_quantity=(SELECT SUM(actual_quantity) FROM purchase_receipt_detail WHERE receipt_id=@rc_id), total_amount=(SELECT SUM(amount) FROM purchase_receipt_detail WHERE receipt_id=@rc_id) WHERE receipt_id=@rc_id;
-- 入库→原料档案(关联supplier_id, 全精度unit_price)
