-- ===== 步骤6: dish_recipe AI生成(unit_price=net_price, total_cost=qty×price) =====

-- ===== 步骤7: dish_cost_card(standard_cost=SUM(recipe.total_cost)) =====
SELECT NULL,1,r.dish_id,d.dish_name,d.dish_category,100.000,100.000,100.00,SUM(r.total_cost),SUM(r.total_cost),d.sale_price,ROUND((d.sale_price-SUM(r.total_cost))/d.sale_price*100,2),'active',NOW(),{esc('成本会计')} FROM dish_recipe r JOIN dish_master d ON r.dish_id=d.dish_id WHERE r.store_id=1 GROUP BY r.dish_id,d.dish_name,d.dish_category,d.sale_price;

-- 注意: dish_master需先插入,cost_card才能JOIN. 见下方步骤8先插dish_master

-- ===== 步骤8: dish_master插入(cost_price留NULL, 后由成本卡回填, 不抄Excel) =====

-- ===== 步骤9: dish_cost_card(standard_cost=SUM(recipe.total_cost), 此时dish_master已存在) =====
DELETE FROM dish_cost_card_detail WHERE store_id=1;
DELETE FROM dish_cost_card WHERE store_id=1;
SELECT NULL,1,r.dish_id,d.dish_name,d.dish_category,100.000,100.000,100.00,SUM(r.total_cost),SUM(r.total_cost),d.sale_price,CASE WHEN d.sale_price<=0 THEN NULL WHEN (d.sale_price-SUM(r.total_cost))/d.sale_price*100>999.99 THEN 999.99 WHEN (d.sale_price-SUM(r.total_cost))/d.sale_price*100<-999.99 THEN -999.99 ELSE ROUND((d.sale_price-SUM(r.total_cost))/d.sale_price*100,2) END,'active',NOW(),'成本会计' FROM dish_recipe r JOIN dish_master d ON r.dish_id=d.dish_id AND d.store_id=1 WHERE r.store_id=1 GROUP BY r.dish_id,d.dish_name,d.dish_category,d.sale_price;
SELECT NULL,1,cc.cost_card_id,r.sort_order,r.ingredient_id,r.ingredient_name,(SELECT im.spec FROM ingredient_master im WHERE im.ingredient_id=r.ingredient_id),r.unit,r.quantity,r.quantity,r.quantity,r.net_unit_price,ROUND(r.quantity*r.net_unit_price,4),r.yield_rate,'标准配方' FROM dish_recipe r JOIN dish_cost_card cc ON r.dish_id=cc.dish_id WHERE r.store_id=1;

-- ===== 步骤10: dish_master.cost_price回填(=成本卡standard_cost, 不抄Excel) =====
UPDATE dish_master dm JOIN dish_cost_card cc ON dm.dish_id=cc.dish_id SET dm.cost_price=cc.standard_cost, dm.cost_rate=CASE WHEN dm.sale_price<=0 THEN NULL WHEN cc.standard_cost/dm.sale_price*100>999.99 THEN 999.99 WHEN cc.standard_cost/dm.sale_price*100<-999.99 THEN -999.99 ELSE ROUND(cc.standard_cost/dm.sale_price*100,2) END WHERE dm.store_id=1;

-- ===== 步骤11: 验证 =====
SET FOREIGN_KEY_CHECKS=1;
SELECT '=== 价格精度(龙虾应0.03424元/克→采购价17.12元/斤) ===' AS info;
SELECT im.ingredient_name,im.unit_price AS 元每克,icp.purchase_unit,icp.purchase_price AS 元每采购单位,icp.conversion_rate,icp.yield_rate,icp.net_price_per_unit AS 净料元每克 FROM ingredient_master im JOIN ingredient_cost_price icp ON im.ingredient_id=icp.ingredient_id WHERE im.ingredient_name IN('龙虾（20头）','五花肉','八角','食用油','花甲') ORDER BY im.ingredient_name;
SELECT '=== net_price公式校验(应=采购价÷换算÷出成率) ===' AS info;
SELECT ingredient_name,ROUND(purchase_price/conversion_rate/(yield_rate/100),8) AS 公式算,net_price_per_unit AS 库存值,CASE WHEN ABS(ROUND(purchase_price/conversion_rate/(yield_rate/100),8)-net_price_per_unit)<0.000001 THEN '正确' ELSE '错误' END AS 校验 FROM ingredient_cost_price WHERE store_id=1 LIMIT 10;
SELECT '=== net_price公式正确率(应100%) ===' AS info;
SELECT COUNT(*) AS 总数,SUM(CASE WHEN ABS(ROUND(purchase_price/conversion_rate/(yield_rate/100),8)-net_price_per_unit)<0.000001 THEN 1 ELSE 0 END) AS 正确数,ROUND(SUM(CASE WHEN ABS(ROUND(purchase_price/conversion_rate/(yield_rate/100),8)-net_price_per_unit)<0.000001 THEN 1 ELSE 0 END)/COUNT(*)*100,2) AS 正确率 FROM ingredient_cost_price WHERE store_id=1;
SELECT '=== amount公式校验(=quantity×unit_price) ===' AS info;
SELECT COUNT(*) AS 总数,SUM(CASE WHEN ABS(ROUND(quantity*unit_price,4)-amount)<0.01 THEN 1 ELSE 0 END) AS 正确数,ROUND(SUM(CASE WHEN ABS(ROUND(quantity*unit_price,4)-amount)<0.01 THEN 1 ELSE 0 END)/COUNT(*)*100,2) AS 正确率 FROM purchase_order_detail WHERE store_id=1;
SELECT '=== total_quantity公式校验(=SUM明细) ===' AS info;
SELECT o.order_no,o.total_quantity AS 主表值,(SELECT SUM(quantity) FROM purchase_order_detail WHERE order_id=o.order_id) AS 明细汇总,CASE WHEN ABS(o.total_quantity-(SELECT SUM(quantity) FROM purchase_order_detail WHERE order_id=o.order_id))<0.01 THEN '正确' ELSE '错误' END AS 校验 FROM purchase_order o WHERE store_id=1;
SELECT '=== 配方/成本卡 ===' AS info;
SELECT COUNT(*) AS 配方行,COUNT(DISTINCT dish_id) AS 覆盖菜数 FROM dish_recipe WHERE store_id=1;
SELECT COUNT(*) AS 成本卡数 FROM dish_cost_card WHERE store_id=1;
SELECT COUNT(*) AS 成本卡明细数 FROM dish_cost_card_detail WHERE store_id=1;
SELECT '=== dish_master.cost_price回填校验(=成本卡,不抄Excel) ===' AS info;
SELECT COUNT(*) AS 总菜数,SUM(CASE WHEN ABS(dm.cost_price-cc.standard_cost)<0.01 THEN 1 ELSE 0 END) AS 与成本卡一致数,ROUND(SUM(CASE WHEN ABS(dm.cost_price-cc.standard_cost)<0.01 THEN 1 ELSE 0 END)/COUNT(*)*100,2) AS 一致率 FROM dish_master dm JOIN dish_cost_card cc ON dm.dish_id=cc.dish_id WHERE dm.store_id=1;
SELECT '=== 供应商关联(应无NULL) ===' AS info;
SELECT COUNT(*) AS 无供应商原料数 FROM ingredient_master WHERE store_id=1 AND primary_supplier_id IS NULL;
SELECT '=== 采购单供应商(FK应存在) ===' AS info;
SELECT o.order_no,o.supplier_id,sm.supplier_name FROM purchase_order o LEFT JOIN supplier_master sm ON o.supplier_id=sm.supplier_id WHERE o.store_id=1;
SELECT '=== 假数据清理(应全0) ===' AS info;
SELECT 'ingredient_purchase' t,COUNT(*) FROM ingredient_purchase WHERE store_id=1 UNION ALL SELECT '孤儿明细',COUNT(*) FROM purchase_order_detail WHERE order_id NOT IN(SELECT order_id FROM purchase_order);
SELECT '=== 全链路抽样(CY000001精美四冷盘) ===' AS info;
SELECT dm.dish_id,dm.dish_name,dm.cost_price,dm.sale_price,dm.cost_rate,cc.standard_cost FROM dish_master dm JOIN dish_cost_card cc ON dm.dish_id=cc.dish_id WHERE dm.dish_id='CY000001';
SELECT dr.ingredient_id,dr.ingredient_name,dr.quantity,dr.unit_price,dr.total_cost FROM dish_recipe dr WHERE dr.dish_id='CY000001' ORDER BY dr.sort_order;
